    {caption:'OptiGrade HCP – Kontrollwerte aus den Schulungsnotizen (Blatt 5)',headers:['Prüfpunkt','Sollwert / Vorgabe','Toleranz'],rows:[['Sondenspitze abmessen','8,5 mm','± 0,5 mm'],['Reflexionsmessung mit Hülse','150','± 3'],['Testblock Stich 1 (hell/dunkel)','8,7 / 60,0 mm','± 0,5 mm'],['Testblock Stich 2 (hell/dunkel)','20,2 / 60,0 mm','± 0,5 mm'],['Teststiche','5 von jeder Seite','—'],['Messstelle Einstich','7 cm (2./3. letzte Rippe)','± 1 cm'],['Messstelle Ausstich','4 cm (Wirbelkörperkante)','± 0,5 cm']]},
    {caption:'Fristen und Pflichten im Überblick (Blatt 2, 4, 10, 11, 12)',headers:['Regelung','Frist / Wert laut Notizen'],rows:[['Verwiegung nach Stechen','Spätestens 45 Minuten'],['Wiegeprotokoll Aufbewahrung','Bis einschließlich komplettes nachfolgendes Kalenderjahr'],['Klassifizierungsprotokoll Aufbewahrung','Mindestens 6 Monate ab Erstellungstag'],['Preismeldepflicht','Schweine 80–110 kg (mind. 60 % pro Woche)'],['Schlachtung Schwellenwerte','Schwein ≥500, Rind ≥150, Schaf ≥75 bzw. 50'],['Eichung Waagen','Unter 3 t: 2 Jahre · Über 3 t: 3 Jahre'],['Klassifizierer Fortbildung','Alle 2 Jahre Wiederholungslehrgang mit Prüfung']]}
